1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  [hidden] { display: none !important; }
10	  body {
11	    margin: 0;
12	    min-height: 100vh;
13	    display: flex;
14	    align-items: center;
15	    justify-content: center;
16	    background: #14161c;
17	    color: #e8e8ec;
18	    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
19	  }
20	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
21	  .board {
22	    display: grid;
23	    grid-template-columns: repeat(10, 28px);
24	    grid-template-rows: repeat(20, 28px);
25	    gap: 1px;
26	    padding: 1px;
27	    background: #2a2d36;
28	    border: 2px solid #3a3e4a;
29	  }
30	  .cell { width: 28px; height: 28px; background: #0d0e12; }
31	  .side { display: flex; flex-direction: column; gap: 16px; min-width: 140px; }
32	  .panel { background: #1d2028; border: 1px solid #2f333d; padding: 10px 12px; }
33	  .label { font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; color: #8a8f9c; }
34	  .value { font-size: 22px; font-weight: 600; margin-top: 2px; }
35	  .next-list { display: flex; flex-direction: column; gap: 10px; margin-top: 8px; }
36	  .next-item[data-piece] { background: transparent !important; }
37	  .preview {
38	    display: grid;
39	    grid-template-columns: repeat(4, 16px);
40	    grid-template-rows: repeat(2, 16px);
41	    gap: 1px;
42	  }
43	  .preview .mini { width: 16px; height: 16px; background: transparent; }
44	  .status { font-size: 14px; color: #ff8a8a; min-height: 18px; }
45	  button {
46	    font: inherit;
47	    background: #2f333d;
48	    color: #e8e8ec;
49	    border: 1px solid #454a57;
50	    padding: 6px 10px;
51	    cursor: pointer;
52	  }
53	  button:hover { background: #3a3e4a; }
54	  .help { font-size: 12px; color: #8a8f9c; line-height: 1.6; }
55	
56	  /* Piece colours, shared by the board and the preview. */
57	  [data-piece="I"] { background: #22c5e6 !important; }
58	  [data-piece="O"] { background: #f2d024 !important; }
59	  [data-piece="T"] { background: #a64ee6 !important; }
60	  [data-piece="S"] { background: #3fcf5a !important; }
61	  [data-piece="Z"] { background: #e8423f !important; }
62	  [data-piece="J"] { background: #3563e9 !important; }
63	  [data-piece="L"] { background: #f08a24 !important; }
64	</style>
65	</head>
66	<body>
67	<div class="game">
68	  <div class="board" data-testid="board" id="board"></div>
69	  <div class="side">
70	    <div class="panel"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
71	    <div class="panel"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
72	    <div class="panel"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
73	    <div class="panel"><div class="label">Next</div><div class="next-list" data-testid="next-piece" id="preview"></div></div>
74	    <div class="status" data-testid="game-over" id="status" hidden>Game over</div>
75	    <button type="button" id="restart">New game</button>
76	    <div class="help">← → move<br>↑ rotate<br>↓ soft drop<br>Space hard drop</div>
77	  </div>
78	</div>
79	<script>
80	(function () {
81	  "use strict";
82	
83	  var ROWS = 20;
84	  var COLS = 10;
85	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
86	  var MIN_UPCOMING = 5;
87	  var PREVIEW_COUNT = 3;
88	
89	  // Spawn shapes as [row, col] offsets from the top-left of the spawn box.
90	  var SHAPES = {
91	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
92	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
93	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
94	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
95	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
96	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
97	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
98	  };
99	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
100	  // Size of the square box each piece rotates inside.
101	  var BOX = { I: 4, O: 2, T: 3, S: 3, Z: 3, J: 3, L: 3 };
102	  // Sideways shifts tried, in order, when a rotated shape does not fit in place.
103	  var KICKS = [0, -1, 1, -2, 2];
104	  // Locking rule (decision): 2 ticks unable to fall, left/right restarts it at most 3 times.
105	  var LOCK_TICKS = 2;
106	  var MAX_LOCK_RESETS = 3;
107	  // Scoring (decision): points by rows cleared at once, times level. Clearing rows together
108	  // must always beat clearing the same rows in smaller groups. Soft drop 1/cell, hard drop 2/cell.
109	  var LINE_SCORES = [0, 100, 300, 500, 800];
110	  var SOFT_DROP_POINTS = 1;
111	  var HARD_DROP_POINTS = 2;
112	
113	  // board[row][col] is a piece letter or null. The renderer and getBoard both read it.
114	  var board;
115	  var current;   // { type, cells, row, col, lockTicks, lockResets } or null
116	  var upcoming;  // array of piece letters, soonest first
117	  var score, level, lines, status;
118	  var timer = null;
119	
120	  var boardEl = document.getElementById("board");
121	  var previewEl = document.getElementById("preview");
122	  var scoreEl = document.getElementById("score");
123	  var levelEl = document.getElementById("level");
124	  var linesEl = document.getElementById("lines");
125	  var statusEl = document.getElementById("status");
126	  var cellEls = [];
127	  var previewItems = [];  // { el, minis } per upcoming piece shown, soonest first
128	
129	  // [REQ-001] Build the 200 board cells and the preview cells once.
130	  // [REQ-004] The preview holds three items, each a 4x2 grid of mini cells.
131	  function buildDom() {
132	    for (var r = 0; r < ROWS; r++) {
133	      cellEls.push([]);
134	      for (var c = 0; c < COLS; c++) {
135	        var el = document.createElement("div");
136	        el.className = "cell";
137	        el.setAttribute("data-testid", "cell");
138	        el.setAttribute("data-row", String(r));
139	        el.setAttribute("data-col", String(c));
140	        el.setAttribute("data-filled", "false");
141	        el.setAttribute("data-piece", "");
142	        boardEl.appendChild(el);
143	        cellEls[r].push(el);
144	      }
145	    }
146	    for (var i = 0; i < PREVIEW_COUNT; i++) {
147	      var item = document.createElement("div");
148	      item.className = "preview next-item";
149	      item.setAttribute("data-testid", "next-piece-item");
150	      item.setAttribute("data-piece", "");
151	      var minis = [];
152	      for (var k = 0; k < 8; k++) {
153	        var m = document.createElement("div");
154	        m.className = "mini";
155	        m.setAttribute("data-piece", "");
156	        item.appendChild(m);
157	        minis.push(m);
158	      }
159	      previewEl.appendChild(item);
160	      previewItems.push({ el: item, minis: minis });
161	    }
162	  }
163	
164	  function emptyBoard() {
165	    var b = [];
166	    for (var r = 0; r < ROWS; r++) {
167	      var row = [];
168	      for (var c = 0; c < COLS; c++) row.push(null);
169	      b.push(row);
170	    }
171	    return b;
172	  }
173	
174	  function isType(t) { return TYPES.indexOf(t) !== -1; }
175	
176	  // [REQ-001] Random generator: a shuffled bag of all seven pieces.
177	  function randomBag() {
178	    var bag = TYPES.slice();
179	    for (var i = bag.length - 1; i > 0; i--) {
180	      var j = Math.floor(Math.random() * (i + 1));
181	      var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
182	    }
183	    return bag;
184	  }
185	
186	  function fillUpcoming() {
187	    while (upcoming.length < MIN_UPCOMING) upcoming = upcoming.concat(randomBag());
188	  }
189	
190	  function cellsOf(piece, row, col) {
191	    return piece.cells.map(function (o) { return [row + o[0], col + o[1]]; });
192	  }
193	
194	  function fits(piece, row, col) {
195	    var cells = cellsOf(piece, row, col);
196	    for (var i = 0; i < cells.length; i++) {
197	      var r = cells[i][0], c = cells[i][1];
198	      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
199	      if (board[r][c]) return false;
200	    }
201	    return true;
202	  }
203	
204	  // [REQ-001] Take the next piece from the queue and place it at the top.
205	  // [REQ-004] If the new piece does not fit where it spawns, the game is over.
206	  function spawn() {
207	    fillUpcoming();
208	    var type = upcoming.shift();
209	    fillUpcoming();
210	    var piece = {
211	      type: type,
212	      cells: SHAPES[type].map(function (o) { return o.slice(); }),
213	      row: 0,
214	      col: SPAWN_COL[type],
215	      lockTicks: 0,
216	      lockResets: 0
217	    };
218	    if (!fits(piece, piece.row, piece.col)) {
219	      current = null;
220	      status = "gameover";
221	      stopTimer();
222	      return;
223	    }
224	    current = piece;
225	  }
226	
227	  // [REQ-003] Remove full rows, drop the rows above, add rows to lines and score at the current level.
228	  function clearLines() {
229	    var kept = board.filter(function (row) {
230	      return row.some(function (v) { return !v; });
231	    });
232	    var cleared = ROWS - kept.length;
233	    while (kept.length < ROWS) {
234	      var empty = [];
235	      for (var c = 0; c < COLS; c++) empty.push(null);
236	      kept.unshift(empty);
237	    }
238	    board = kept;
239	    if (cleared > 0) {
240	      score += LINE_SCORES[cleared] * level;
241	      lines += cleared;
242	      var newLevel = Math.floor(lines / 10) + 1;
243	      if (newLevel !== level) {
244	        level = newLevel;
245	        if (status === "running") startTimer();
246	      }
247	    }
248	  }
249	
250	  // [REQ-001] Lock the falling piece into the board, clear lines, spawn the next piece.
251	  function lockPiece() {
252	    cellsOf(current, current.row, current.col).forEach(function (rc) {
253	      board[rc[0]][rc[1]] = current.type;
254	    });
255	    current = null;
256	    clearLines();
257	    spawn();
258	  }
259	
260	  // [REQ-001] One gravity step. The real timer and __tetris.tick both call this.
261	  // [REQ-002] A step that cannot move the piece down counts one tick of lock delay.
262	  function gravityStep() {
263	    if (status !== "running" || !current) return;
264	    if (fits(current, current.row + 1, current.col)) {
265	      current.row += 1;
266	      current.lockTicks = 0;
267	    } else {
268	      current.lockTicks += 1;
269	      if (current.lockTicks >= LOCK_TICKS) lockPiece();
270	    }
271	  }
272	
273	  // [REQ-002] Sideways move. While resting, a move restarts the lock delay, at most 3 times per piece.
274	  function shift(dx) {
275	    if (!fits(current, current.row, current.col + dx)) return;
276	    var resting = !fits(current, current.row + 1, current.col);
277	    current.col += dx;
278	    if (resting && current.lockResets < MAX_LOCK_RESETS) {
279	      current.lockResets += 1;
280	      current.lockTicks = 0;
281	    }
282	  }
283	
284	  // [REQ-002] Rotate clockwise inside the piece's box; try sideways shifts; refuse if none fit.
285	  function rotateCW() {
286	    var n = BOX[current.type];
287	    var rotated = { type: current.type, cells: current.cells.map(function (o) { return [o[1], n - 1 - o[0]]; }) };
288	    for (var i = 0; i < KICKS.length; i++) {
289	      if (fits(rotated, current.row, current.col + KICKS[i])) {
290	        current.cells = rotated.cells;
291	        current.col += KICKS[i];
292	        return;
293	      }
294	    }
295	  }
296	
297	  // [REQ-001] Player actions: left, right, softDrop, hardDrop. [REQ-002] rotateCW.
298	  // [REQ-003] Soft drop scores 1 per cell moved, hard drop 2 per cell dropped.
299	  function doInput(action) {
300	    if (status !== "running" || !current) return;
301	    if (action === "left") {
302	      shift(-1);
303	    } else if (action === "right") {
304	      shift(1);
305	    } else if (action === "rotateCW") {
306	      rotateCW();
307	    } else if (action === "softDrop") {
308	      if (fits(current, current.row + 1, current.col)) {
309	        current.row += 1;
310	        score += SOFT_DROP_POINTS;
311	      }
312	    } else if (action === "hardDrop") {
313	      while (fits(current, current.row + 1, current.col)) {
314	        current.row += 1;
315	        score += HARD_DROP_POINTS;
316	      }
317	      lockPiece();
318	    }
319	  }
320	
321	  function gravityInterval() {
322	    return Math.max(100, 1000 - (level - 1) * 90);
323	  }
324	
325	  function stopTimer() {
326	    if (timer !== null) { clearInterval(timer); timer = null; }
327	  }
328	
329	  function startTimer() {
330	    stopTimer();
331	    timer = setInterval(function () {
332	      gravityStep();
333	      render();
334	    }, gravityInterval());
335	  }
336	
337	  // [REQ-001] Draw the whole game state into the DOM, synchronously.
338	  function render() {
339	    var drawn = board.map(function (row) { return row.slice(); });
340	    if (current) {
341	      cellsOf(current, current.row, current.col).forEach(function (rc) {
342	        drawn[rc[0]][rc[1]] = current.type;
343	      });
344	    }
345	    for (var r = 0; r < ROWS; r++) {
346	      for (var c = 0; c < COLS; c++) {
347	        var v = drawn[r][c] || "";
348	        var el = cellEls[r][c];
349	        if (el.getAttribute("data-piece") !== v) {
350	          el.setAttribute("data-piece", v);
351	          el.setAttribute("data-filled", v ? "true" : "false");
352	        }
353	      }
354	    }
355	    // [REQ-004] Next three pieces, soonest first, each in its board colour.
356	    previewItems.forEach(function (item, i) {
357	      var type = upcoming[i] || "";
358	      item.el.setAttribute("data-piece", type);
359	      item.el.hidden = !type;
360	      item.minis.forEach(function (m) { m.setAttribute("data-piece", ""); });
361	      if (type) {
362	        SHAPES[type].forEach(function (o) {
363	          item.minis[o[0] * 4 + o[1]].setAttribute("data-piece", type);
364	        });
365	      }
366	    });
367	    scoreEl.textContent = String(score);
368	    levelEl.textContent = String(level);
369	    linesEl.textContent = String(lines);
370	    statusEl.hidden = status !== "gameover";
371	  }
372	
373	  // [REQ-001] Start a fresh game, optionally from a fixed piece queue.
374	  function newGame(queue) {
375	    board = emptyBoard();
376	    score = 0;
377	    level = 1;
378	    lines = 0;
379	    status = "running";
380	    upcoming = Array.isArray(queue) ? queue.filter(isType) : [];
381	    current = null;
382	    spawn();
383	    if (status === "running") startTimer();
384	    render();
385	  }
386	
387	  window.__tetris = {
388	    newGame: function (queue) { newGame(queue); },
389	
390	    setQueue: function (queue) {
391	      upcoming = Array.isArray(queue) ? queue.filter(isType) : [];
392	      fillUpcoming();
393	      render();
394	    },
395	
396	    setBoard: function (rows) {
397	      var b = emptyBoard();
398	      for (var r = 0; r < ROWS; r++) {
399	        var line = (rows && rows[r]) || "";
400	        for (var c = 0; c < COLS; c++) {
401	          var ch = line.charAt(c);
402	          b[r][c] = isType(ch) ? ch : null;
403	        }
404	      }
405	      board = b;
406	      render();
407	    },
408	
409	    tick: function (n) {
410	      if (n === undefined) n = 1;
411	      for (var i = 0; i < n; i++) gravityStep();
412	      if (status === "running") startTimer();
413	      render();
414	    },
415	
416	    input: function (action) {
417	      doInput(action);
418	      render();
419	    },
420	
421	    getBoard: function () {
422	      return board.map(function (row) {
423	        return row.map(function (v) { return v || "."; }).join("");
424	      });
425	    },
426	
427	    getState: function () {
428	      return {
429	        current: current
430	          ? { type: current.type, cells: cellsOf(current, current.row, current.col) }
431	          : null,
432	        next: upcoming.slice(),
433	        score: score,
434	        level: level,
435	        lines: lines,
436	        status: status
437	      };
438	    }
439	  };
440	
441	  var KEYS = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", " ": "hardDrop" };
442	
443	  document.addEventListener("keydown", function (e) {
444	    var action = KEYS[e.key];
445	    if (!action) return;
446	    e.preventDefault();
447	    window.__tetris.input(action);
448	  });
449	
450	  document.getElementById("restart").addEventListener("click", function (e) {
451	    e.currentTarget.blur();
452	    newGame();
453	  });
454	
455	  buildDom();
456	  newGame();
457	})();
458	</script>
459	</body>
460	</html>
