// [REQ-003] Soft drop scores 1 per cell moved, hard drop 2 per cell dropped.
// [REQ-005] Soft drop on a resting piece scores nothing but restarts the lock delay like a sideways move.
function doInput(action) {
  if (status !== "running" || !current) return;
  if (action === "left") {
    shift(-1);
  } else if (action === "right") {
    shift(1);
